package ch.qos.logback.core.model;
import java.util.Objects;
public class PropertyModel extends NamedModel { private static final long serialVersionUID=1494176979175092052L; String value,scopeStr,file,resource; public PropertyModel(){} public PropertyModel makeNewInstance(){return new PropertyModel();} public void mirror(Model m){super.mirror(m);PropertyModel p=(PropertyModel)m;value=p.value;scopeStr=p.scopeStr;file=p.file;resource=p.resource;} public String getValue(){return value;} public void setValue(String v){value=v;} public String getScopeStr(){return scopeStr;} public void setScopeStr(String v){scopeStr=v;} public String getFile(){return file;} public void setFile(String v){file=v;} public String getResource(){return resource;} public void setResource(String v){resource=v;} public int hashCode(){return 31*super.hashCode()+Objects.hash(file,resource,scopeStr,value);} public boolean equals(Object o){if(this==o)return true;if(!(o instanceof PropertyModel)||!super.equals(o))return false;PropertyModel p=(PropertyModel)o;return Objects.equals(file,p.file)&&Objects.equals(resource,p.resource)&&Objects.equals(scopeStr,p.scopeStr)&&Objects.equals(value,p.value);} }
